<div class="section-heading"><div><div class="eyebrow">Operação</div><h1><?=$professional?'Minhas vendas':'PDV / Vendas'?></h1></div></div><div class="card mb-4"><div class="card-body"><form method="post" action="/sales" class="row g-3"><?php echo \App\Core\CSRF::field();?><div class="col-md-4"><label class="form-label">Produto</label><select class="form-select" name="product_id" required><option value="">Selecione</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?> · R$ <?=number_format($p['sale_price'],2,',','.')?><?=$stockEnabled?' · estoque '.$p['stock']:''?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Cliente</label><select class="form-select" name="customer_id"><option value="">Balcão / avulsa</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-1"><label class="form-label">Qtd.</label><input class="form-control" type="number" step=".001" min=".001" name="quantity" value="1"></div><div class="col-md-2"><label class="form-label">Desconto R$</label><input class="form-control" type="number" step=".01" min="0" name="discount" value="0" <?=\App\Core\Authorization::allows('sales.discount')?'':'readonly title="Sem permissão para desconto"'?>></div><div class="col-md-2"><label class="form-label">Pagamento</label><select class="form-select" name="payment_method"><option value="pix">PIX</option><option value="dinheiro">Dinheiro</option><option value="credito">Crédito</option><option value="debito">Débito</option><option value="outro">Outro</option></select></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary w-100">Vender</button></div></form><?php if(!$stockEnabled):?><div class="form-text mt-2">Controle de estoque não contratado: a venda é registrada sem movimentação de saldo.</div><?php endif;?></div></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data</th><th>Profissional</th><th>Cliente</th><th>Total</th><th>Forma</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><?=htmlspecialchars($s['created_at'])?></td><td><?=htmlspecialchars($s['professional_name']??'Proprietário/balcão')?></td><td><?=htmlspecialchars($s['customer_name']??'-')?></td><td>R$ <?=number_format((float)$s['total'],2,',','.')?></td><td><?=htmlspecialchars($s['payment_method'])?></td><td><span class="badge text-bg-<?=$s['status']==='completed'?'success':'secondary'?>"><?=htmlspecialchars(['completed'=>'Concluída','cancelled'=>'Cancelada','pending'=>'Pendente'][$s['status']]??$s['status'])?></span></td><td class="text-end"><?php if($s['status']==='completed'&&\App\Core\Authorization::allows('sales.cancel')):?><form method="post" action="/sales/<?=(int)$s['id']?>/cancel" class="d-inline" onsubmit="const r=prompt('Motivo do cancelamento:');if(!r)return false;this.reason.value=r;"><?php echo \App\Core\CSRF::field();?><input type="hidden" name="reason"><button class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="7" class="text-center py-5 text-secondary">Nenhuma venda registrada.</td></tr><?php endif;?></tbody></table></div></div>
